<?php
require __DIR__.'/page-control.php';
require_once dirname(__DIR__,2).'/neptune_secure/community-external-scouting.php';
$db->exec('CREATE TABLE community_external_imports(id TEXT PRIMARY KEY,season INT,event_key TEXT,provider TEXT,adapter_version TEXT,source_url TEXT,file_sha256 TEXT,enabled INT DEFAULT 1,timing_offset_ms INT DEFAULT 0,report_json TEXT,created_by INT,created_at INT,UNIQUE(provider,event_key,file_sha256,timing_offset_ms))');
