$csv="match,team,scouter,auto_fuel_score,tele_fuel_score,tele_climb_level,timeline\nqm1,1,A PRIVATE NAME,5,1,3,18:auto_fuel_score:5 24:tele_fuel_score 158:tele_climb_level 159:tele_climb_level 160:tele_climb_level\n";
$p=CommunityExternalScouting::parse($csv,'2026week0');ok($p['report']['robot_records']===1&&$p['report']['fuel_entries']===2,'source preview counts counted activity without inventing scoring cycles');ok(!str_contains(json_encode($p),'A PRIVATE NAME'),'scouter identity is dropped before source records are persisted');
$svc=new CommunityExternalScouting($db);$before=(int)$db->query('SELECT COUNT(*) FROM community_video_labels')->fetchColumn();rejects(fn()=>$svc->save($p,7,'https://public.viperscout.com/export.html#event=2026week0'),'no-video import is blocked before any source is saved');ok((int)$db->query('SELECT COUNT(*) FROM community_external_imports')->fetchColumn()===0,'blocked upload writes no imports');$q=$db->prepare('INSERT INTO community_matches VALUES(3,?,?,?,?)');$q->execute(['2026week0_qm1','Week zero Q1','https://www.youtube.com/watch?v=CCCCCCCCCCC',json_encode(['red'=>[1,2,3],'blue'=>[4,5,6]])]);$saved=$svc->save($p,7,'https://public.viperscout.com/export.html#event=2026week0');ok($svc->save($p,7,'https://public.viperscout.com/export.html#event=2026week0')['id']===$saved['id'],'repeat file import is idempotent');
ok($svc->videoCheck($p)['ready'],'all matched source robots pass the video gate');
$rows=$svc->training(2026);ok(count($rows)===3,'two fuel activities and the final climb outcome are mapped');ok($rows[0]['time_basis']==='phase_elapsed_ms'&&$rows[1]['start_ms']===1000&&$rows[1]['external']['phase']==='teleop','Viper 23-second teleop origin is preserved for later video anchoring');ok($rows[0]['external']['quantity']===5&&$rows[0]['scoring']===null,'counted fuel is not converted into a point target');ok($rows[2]['tag_key']==='end_completed'&&$rows[2]['start_ms']===137000,'incremental climb clicks map only the final reported height');
$export=community_learning_export($db);ok(str_contains($export,'external_scouting_label')&&!str_contains($export,'A PRIVATE NAME'),'training snapshot includes attributed outside activity without scouter names');
$svc->toggle($saved['id'],false,2026);ok($svc->training(2026)===[]&&(int)$db->query('SELECT COUNT(*) FROM community_external_observations')->fetchColumn()===1,'excluding a source keeps its original records');$svc->toggle($saved['id'],true,2026);
$other=CommunityExternalScouting::parse(str_replace(',5,1,3,',',6,1,3,',$csv),'2026week0');$second=$svc->save($other,7,'https://public.viperscout.com/export.html#event=2026week0');ok($svc->training(2026)===[]&&str_contains($svc->resolved(2026)['problems'][0]['reason'],'Conflicting'),'conflicting active versions are excluded, never silently chosen');$svc->toggle($second['id'],false,2026);ok(count($svc->training(2026))===3,'excluding the conflicting source restores the intended source version');
$bad=CommunityExternalScouting::parse(str_replace('qm1,1,','qm1,999,',$csv),'2026week0');rejects(fn()=>$svc->save($bad,7,'https://public.viperscout.com/export.html#event=2026week0'),'robots outside the catalog roster cannot be imported');
rejects(fn()=>CommunityExternalScouting::parse($csv,'2025week0'),'other games require their own adapter');rejects(fn()=>$svc->save($p,7,'https://public.viperscout.com/export.html#event=2026ctsou'),'source attribution must match the imported event');ok((int)$db->query('SELECT COUNT(*) FROM community_video_labels')->fetchColumn()===$before,'importing and excluding outside scouting never alters community tags');
$bundle=json_encode(['/data/2026week0.scouting.csv'=>$csv,'/data/2026week0.event.csv'=>"name,start,end\nWeek Zero,2026-02-21,2026-02-21\n",'/data/2026week0.pit.csv'=>"PRIVATE PIT CONTACTS"]);
$json=CommunityExternalScouting::parse($bundle,'');ok($json['event_key']==='2026week0'&&$json['report']['input_format']==='viper-event-json'&&$json['report']['event_start']==='2026-02-21','event bundles auto-detect event identity and show event dates');
ok($json['records']===$p['records']&&$json['file_sha256']===$p['file_sha256'],'JSON uses the same observations and deduplication identity as its embedded CSV');
ok($svc->save($json,7,'https://public.viperscout.com/export.html#event=2026week0')['id']===$saved['id'],'importing the JSON version of an existing CSV does not duplicate it');
ok(!str_contains(json_encode($json),'PRIVATE PIT CONTACTS')&&!str_contains(json_encode($json),'A PRIVATE NAME'),'unrelated bundle contents and scouter names are not persisted');
rejects(fn()=>CommunityExternalScouting::parse($bundle,'2026ctsou'),'JSON cannot be reassigned to a different event');
rejects(fn()=>CommunityExternalScouting::parse('{"broken":','2026week0'),'malformed JSON rejected clearly');
rejects(fn()=>CommunityExternalScouting::parse('[{"team":1}]','2026week0'),'unmapped arbitrary JSON arrays are rejected');
rejects(fn()=>CommunityExternalScouting::parse(json_encode(['/data/2026week0.scouting.csv'=>$csv,'/data/2026ctsou.event.csv'=>'mixed']),'2026week0'),'mixed-event bundles are rejected');
rejects(fn()=>CommunityExternalScouting::parse(json_encode(['/data/2026week0.scouting.csv'=>['not'=>'text']]),'2026week0'),'non-text embedded data rejected');

$partial=CommunityExternalScouting::parse($csv."qm2,2,A PRIVATE NAME,5,1,3,18:auto_fuel_score:5\n",'2026week0');$check=$svc->videoCheck($partial);ok(!$check['ready']&&$check['matches_found']===1&&$check['matches_total']===2,'partial video coverage lists found and missing matches');rejects(fn()=>$svc->save($partial,7,'https://public.viperscout.com/export.html#event=2026week0'),'partial coverage cannot bypass the server import gate');
$db->exec("UPDATE community_matches SET source_url='' WHERE id=3");rejects(fn()=>$svc->save($p,7,'https://public.viperscout.com/export.html#event=2026week0'),'save rechecks links even after a previously passing preview');$db->exec("UPDATE community_matches SET source_url='https://www.youtube.com/watch?v=CCCCCCCCCCC' WHERE id=3");
$jobs=$db->query('SELECT * FROM community_learning_jobs ORDER BY id')->fetchAll(PDO::FETCH_ASSOC);$svc->archiveEvent('2026week0',2026);ok($svc->training(2026)===[]&&count($svc->records($saved['id'],2026)['records'])===1,'remove event excludes future training but keeps recoverable records');ok($svc->imports(2026)[0]['archived']&&!$svc->imports(2026)[0]['enabled'],'removed imports are visibly archived and cannot be mistaken for enabled');$svc->archiveEvent('2026week0',2026,true);ok(!$svc->imports(2026)[0]['archived']&&!$svc->imports(2026)[0]['enabled'],'restoring an event does not silently re-enable it');ok($jobs===$db->query('SELECT * FROM community_learning_jobs ORDER BY id')->fetchAll(PDO::FETCH_ASSOC),'removing and restoring events never alters running or saved training jobs');
require_once dirname(__DIR__,2).'/neptune_secure/community-catalog.php';$known=CommunityCatalog::sourceEvents()['2026kett'];ok(count($known['matches'])===15,'all fifteen discovered Kettering qualification uploads are in the source catalog');foreach($known['matches'] as $m){$normalized=CommunityCatalog::normalize($m,'2026kett',$known['name']);ok($normalized['ready']===1,'curated '.$m['key'].' has a video link and six schedule positions');}
